                                ]
                            },
                            "group": {
                                "type": "array",
                                "items": {}
                            }
                        },
                        "required": [
                            "type",
                            "property",
                            "group"
                        ]
                    },
                    "id": {
                        "type": "string",
                        "default": "ctr1"
                    }
                },
                "required": [
